const e = $input.first()?.json ?? {};
const execution = e.execution ?? {};
const workflow = e.workflow ?? {};
const error = execution.error ?? {};

return [{
  json: {
    asunto: '[ERROR] TSK-AU-02 - Sincronización de festivos Colombia',
    workflow: workflow.name ?? 'Workflow desconocido',
    ejecucionUrl: execution.url ?? '',
    ultimoNodo: execution.lastNodeExecuted ?? 'No identificado',
    mensaje: error.message ?? e.message ?? 'Error sin detalle disponible',
    fecha: new Date().toISOString()
  }
}];

